-- C-025: medals v2 (from Cowork, celsu-C-025-badges-migration.sql): backups, new badge columns, all 38 medals
-- (unbuilt rules stay active=false), my_new_badges() no longer marks medals seen, ack_badges() does.

create table if not exists private.badges_backup_20261028 as select * from public.badges;
create table if not exists private.gamification_badges_backup_20261028 as select user_id, badges from public.gamification;
alter table public.badges add column if not exists icon text, add column if not exists tier text, add column if not exists emblem_url text,
