/course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/badges/citizen_ready.mp3','[0, 0.313, 0.592]'::jsonb,false)
on conflict (code) do update set name=excluded.name, requirement=excluded.requirement, rule=excluded.rule,
 color=coalesce(public.badges.color, excluded.color), sort_order=excluded.sort_order, active=excluded.active, icon=excluded.icon, tier=excluded.tier,
 emblem_url=excluded.emblem_url, category=excluded.category, phrase_en=excluded.phrase_en, phrase_es=excluded.phrase_es,
 phrase_audio=excluded.phrase_audio, phrase_wt=excluded.phrase_wt, is_new=excluded.is_new;
drop function if exists public.my_new_badges();
create function public.my_new_badges()
 returns table(code text, name text, color text, requirement text, icon text, tier text, emblem_url text, category text, phrase_en text, phrase_es text, phrase_audio text, phrase_wt jsonb, earned_at timestamptz)
 language plpgsql security definer set search_path to ''
as $f$
declare uid uuid := (select auth.uid()); have jsonb;
begin
  if uid is null then return; end if;
  perform private.award_badges(uid);
  select badges into have from public.gamification where user_id = uid;
  return query
    select b.code, b.name, b.color, b.requirement, b.icon, b.tier, b.emblem_url, b.category, b.phrase_en, b.phrase_es, b.phrase_audio, b.phrase_wt, (e.v->>'at')::timestamptz
      from jsonb_each(coalesce(case when jsonb_typeof(have)='object' then have end,'{}'::jsonb)) e(k,v)
      join public.badges b on b.code = e.k
     where coalesce((e.v->>'seen')::boolean, true) = false
     order by array_position(array['diamond','platinum','gold','silver','bronze'], b.tier), b.sort_order;
end $f$;
grant execute on function public.my_new_badges() to authenticated;
create or replace function public.ack_badges(codes text[])
 returns void language plpgsql security definer set search_path to ''
as $f$
declare uid uuid := (select auth.uid());
begin
  if uid is null or codes is null then return; end if;
  update public.gamification
     set badges = (select jsonb_object_agg(k, case when k = any(codes) then v || jsonb_build_object('seen', true, 'seen_at', now()) else v end) from jsonb_each(badges) e(k, v))
   where user_id = uid and jsonb_typeof(badges) = 'object';
end $f$;
revoke all on function public.ack_badges(text[]) from public, anon;
grant execute on function public.ack_badges(text[]) to authenticated;
